-- UI-01 / API-01 1-Table sample (PostgreSQL / init-pilot conventions)

CREATE SCHEMA IF NOT EXISTS app;

DROP TABLE IF EXISTS app."WorkNotice";

CREATE TABLE app."WorkNotice"
(
    "WorkNoticeId"      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "WorkNoticeGuid"    UUID NOT NULL DEFAULT gen_random_uuid(),
    "WorkNoticeCode"    VARCHAR(20) NOT NULL,
    "WorkNoticeName"    VARCHAR(200) NOT NULL,
    "WorkNoticeDate"    DATE NOT NULL,
    "IsEditAble"        BOOLEAN NOT NULL DEFAULT TRUE,
    "Note"              VARCHAR(500),
    "StatusId"          INT NOT NULL DEFAULT 1,
    "RowVersion"        BYTEA NOT NULL DEFAULT '\x0000000000000000',
    "CreatedById"       BIGINT NOT NULL,
    "CreatedTime"       TIMESTAMPTZ NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    "UpdatedById"       BIGINT,
    "UpdatedTime"       TIMESTAMPTZ,
    "DeletedById"       BIGINT,
    "DeletedTime"       TIMESTAMPTZ,
    CONSTRAINT "UQ_WorkNotice_WorkNoticeGuid" UNIQUE ("WorkNoticeGuid"),
    CONSTRAINT "UQ_WorkNotice_Code" UNIQUE ("WorkNoticeCode"),
    CONSTRAINT "CHK_WorkNotice_Status" CHECK ("StatusId" IN (0, 1, 2))
);

CREATE INDEX "IX_WorkNotice_WorkNoticeDate_Active"
    ON app."WorkNotice" ("WorkNoticeDate")
    INCLUDE ("WorkNoticeGuid", "WorkNoticeName")
    WHERE ("DeletedTime" IS NULL AND "StatusId" > 0);

